class HoverButton(tk.Button):
    """A tk.Button with a hover color, since ttk styling for colored
    buttons is unreliable across platforms."""

    def __init__(self, master, bg, hover_bg, fg="white", **kwargs):
        super().__init__(
            master,
            bg=bg,
            fg=fg,
            activebackground=hover_bg,
            activeforeground=fg,
            relief="flat",
            bd=0,
            cursor="hand2",
            highlightthickness=0,
            **kwargs,
        )
        self._bg = bg
        self._hover_bg = hover_bg
        self.bind("<Enter>", lambda e: self.configure(bg=self._hover_bg))
        self.bind("<Leave>", lambda e: self.configure(bg=self._bg))


class Card(tk.Frame):
    """A white 'card' surface with a hairline border, used to visually
    group related controls."""

    def __init__(self, master, **kwargs):
        outer = tk.Frame(master, bg=Theme.border)
        outer.pack_propagate(True)
        super().__init__(outer, bg=Theme.card, **kwargs)
        self.pack(fill="both", expand=True, padx=1, pady=1)
        self._outer = outer

    def grid_into(self, **grid_kwargs):
        self._outer.grid(**grid_kwargs)
        return self

    def pack_into(self, **pack_kwargs):
        self._outer.pack(**pack_kwargs)
        return self


def section_label(parent, icon, text):
    row = tk.Frame(parent, bg=Theme.card)
    row.pack(fill="x", pady=(0, 6))
    tk.Label(
        row, text=icon, font=(FONT_FAMILY, 12), bg=Theme.card, fg=Theme.accent,
    ).pack(side="left")
    tk.Label(
        row, text=text, font=(FONT_FAMILY, 10, "bold"), bg=Theme.card, fg=Theme.text,
    ).pack(side="left", padx=(6, 0))
    return row


