class LogConsole:
    """A log panel (ScrolledText) that lives inside a card, plus an
    optional pop-out window that mirrors the same log - shared by both
    tools so they behave identically."""

    def __init__(self, root, parent_card, height=13):
        self.root = root
        self.log_window = None
        self.popout_log_text = None

        header_row = tk.Frame(parent_card, bg=Theme.card)
        header_row.pack(fill="x", pady=(0, 4))
        tk.Label(
            header_row, text="Log", font=(FONT_FAMILY, 9, "bold"),
            bg=Theme.card, fg=Theme.text_muted, anchor="w",
        ).pack(side="left")
        HoverButton(
            header_row, bg="#e2e8f0", hover_bg="#cbd5e1", fg=Theme.text,
            text="\u2197 Open log in new window", font=(FONT_FAMILY, 8, "bold"),
            padx=8, pady=3, command=self.open_window,
        ).pack(side="right")

        self.log_text = scrolledtext.ScrolledText(
            parent_card, height=height, state="disabled", bg=Theme.log_bg, fg=Theme.log_fg,
            font=("Consolas", 9), relief="flat", bd=0, padx=8, pady=6,
        )
        self.log_text.pack(fill="both", expand=True)
        self._configure_tags(self.log_text)

    @staticmethod
    def _configure_tags(widget):
        widget.tag_configure("ok", foreground="#6fcf7c")
        widget.tag_configure("missing", foreground="#f2726c")
        widget.tag_configure("skip", foreground="#f2c14e")
        widget.tag_configure("info", foreground="#7fd9d4")
        widget.tag_configure("error", foreground="#f2726c")

    def log(self, message, tag=None):
        self.log_text.configure(state="normal")
        self.log_text.insert("end", message + "\n", tag if tag else ())
        self.log_text.see("end")
        self.log_text.configure(state="disabled")
        self.log_text.update_idletasks()

        if self.popout_log_text is not None:
            try:
                self.popout_log_text.configure(state="normal")
                self.popout_log_text.insert("end", message + "\n", tag if tag else ())
                self.popout_log_text.see("end")
                self.popout_log_text.configure(state="disabled")
                self.popout_log_text.update_idletasks()
            except tk.TclError:
                self.log_window = None
                self.popout_log_text = None

    def clear(self):
        self.log_text.configure(state="normal")
        self.log_text.delete("1.0", "end")
        self.log_text.configure(state="disabled")
        if self.popout_log_text is not None:
            try:
                self.popout_log_text.configure(state="normal")
                self.popout_log_text.delete("1.0", "end")
                self.popout_log_text.configure(state="disabled")
            except tk.TclError:
                self.log_window = None
                self.popout_log_text = None

    def open_window(self):
        if self.log_window is not None and self.log_window.winfo_exists():
            self.log_window.deiconify()
            self.log_window.lift()
            self.log_window.focus_force()
            return

        self.log_window = tk.Toplevel(self.root)
        self.log_window.title("PGMO Project Suite \u2014 Log")
        self.log_window.geometry("780x540")
        self.log_window.configure(bg=Theme.bg)
        self.log_window.protocol("WM_DELETE_WINDOW", self._close_window)

        header = tk.Frame(self.log_window, bg=Theme.bg)
        header.pack(fill="x", padx=16, pady=(14, 6))
        tk.Label(
            header, text="Log", font=(FONT_FAMILY, 12, "bold"),
            bg=Theme.bg, fg=Theme.text,
        ).pack(side="left")

        self.popout_log_text = scrolledtext.ScrolledText(
            self.log_window, state="disabled", bg=Theme.log_bg, fg=Theme.log_fg,
            font=("Consolas", 10), relief="flat", bd=0, padx=10, pady=8,
        )
        self.popout_log_text.pack(fill="both", expand=True, padx=16, pady=(0, 16))
        self._configure_tags(self.popout_log_text)

        existing = self.log_text.get("1.0", "end-1c")
        if existing:
            self.popout_log_text.configure(state="normal")
            self.popout_log_text.insert("end", existing)
            self.popout_log_text.see("end")
            self.popout_log_text.configure(state="disabled")

    def _close_window(self):
        if self.log_window is not None:
            self.log_window.destroy()
        self.log_window = None
        self.popout_log_text = None


class LoadingSpinner:
    """A tiny inline spinner + rotating status message. Each tool passes in
    its own list of messages (see PDF_MERGE_MESSAGES / ID_SEARCH_MESSAGES /
    EXCEL_MERGE_MESSAGES above) so the "it's working" feedback feels
    specific to what that tool is actually doing, instead of a generic
    "Running..." for every job."""

    FRAMES = ["\u25D0", "\u25D3", "\u25D1", "\u25D2"]  # ◐ ◓ ◑ ◒ (rotating disc)

    def __init__(self, label_widget, dot_widget=None):
        self.label = label_widget
        self.dot = dot_widget
        self._running = False
        self._frame_idx = 0
        self._msg_idx = 0
        self._messages = ["Working..."]
        self._job = None

    def start(self, messages=None):
        self._messages = list(messages) if messages else ["Working..."]
        self._frame_idx = 0
        self._msg_idx = 0
        self._running = True
        self._tick()

    def _tick(self):
        if not self._running:
            return
        frame = self.FRAMES[self._frame_idx % len(self.FRAMES)]
        msg = self._messages[self._msg_idx % len(self._messages)]
        try:
            self.label.configure(text=f"{frame}  {msg}", fg=Theme.warning)
            if self.dot is not None:
                self.dot.configure(fg=Theme.warning)
        except tk.TclError:
            self._running = False
            return
        self._frame_idx += 1
        if self._frame_idx % 9 == 0:
            self._msg_idx += 1
        self._job = self.label.after(120, self._tick)

    def stop(self, text, color):
        self._running = False
        if self._job is not None:
            try:
                self.label.after_cancel(self._job)
            except tk.TclError:
                pass
            self._job = None
        try:
            self.label.configure(text=text, fg=color)
            if self.dot is not None:
                self.dot.configure(fg=color)
        except tk.TclError:
            pass


def build_run_bar(parent, button_text, command):
    """Run button + status dot/label + indeterminate progress bar. Returns
    (run_button, set_status_fn, progress_bar, spinner)."""
    run_row = tk.Frame(parent, bg=Theme.card)
    run_row.pack(fill="x", pady=(0, 10))

    run_button = HoverButton(
        run_row, bg=Theme.accent, hover_bg=Theme.accent_hover,
        text=button_text, font=(FONT_FAMILY, 11, "bold"),
        padx=14, pady=8, command=command,
    )
    run_button.pack(side="left")

    status_wrap = tk.Frame(run_row, bg=Theme.card)
    status_wrap.pack(side="left", padx=14)
    status_dot = tk.Label(status_wrap, text="\u25CF", font=(FONT_FAMILY, 10), bg=Theme.card, fg=Theme.text_muted)
    status_dot.pack(side="left")
    status_label = tk.Label(status_wrap, text="Ready", font=(FONT_FAMILY, 10), bg=Theme.card, fg=Theme.text_muted)
    status_label.pack(side="left", padx=(6, 0))

    progress = ttk.Progressbar(parent, mode="indeterminate", style="PGMO.Horizontal.TProgressbar")
    progress.pack(fill="x", pady=(0, 10))

    def set_status(text, color):
        status_label.configure(text=text, fg=color)
        status_dot.configure(fg=color)

    spinner = LoadingSpinner(status_label, status_dot)

    return run_button, set_status, progress, spinner


# ---------------------------------------------------------------------------
# Tool 1: PDF Merger - core logic (unchanged behavior from the original
# command-line / single-purpose version)
# ---------------------------------------------------------------------------

def build_filename_index(folder):
    files = []
    for name in os.listdir(folder):
        if name.lower().endswith(".pdf"):
            files.append((name, os.path.join(folder, name)))
    return files


def find_match(needle, files):
    if not needle:
        return None
    needle_lower = needle.lower()
    for name, full_path in files:
        if needle_lower in name.lower():
            return full_path
    return None


def resolve_row(col_a, col_b, files):
    if col_a:
        path = find_match(col_a, files)
        if path:
            return path, "A"
    if col_b:
        b_formatted = "00" + col_b.strip()
        path = find_match(b_formatted, files)
        if path:
            return path, "B"
    return None, None


def run_merge(order_list, source_folder, output_path, log_fn):
    """
    order_list: list of (col_a, col_b) tuples
    log_fn: function that accepts (message, tag) and displays it
    Returns (merged_count, missing_rows) or raises an Exception on fatal errors.
    """
    if not os.path.isdir(source_folder):
        raise ValueError(f"Source folder not found:\n{source_folder}")

    files = build_filename_index(source_folder)
    if not files:
        raise ValueError(f"No PDF files found in:\n{source_folder}")

    writer = PdfWriter()
    seen_paths = set()
    merged_count = 0
    missing_rows = []

    for i, (col_a, col_b) in enumerate(order_list, start=1):
        path, matched_via = resolve_row(col_a, col_b, files)

        if path is None:
            missing_rows.append((i, col_a, col_b))
            log_fn(f"[{i:>3}]  MISSING   A='{col_a}'  B='{col_b}'  ->  no matching PDF found", "missing")
            continue

        if path in seen_paths:
            log_fn(f"[{i:>3}]  SKIP dup  A='{col_a}'  B='{col_b}'  ->  {os.path.basename(path)}", "skip")
            continue

        reader = PdfReader(path)
        for page in reader.pages:
            writer.add_page(page)

        seen_paths.add(path)
        merged_count += 1
        log_fn(f"[{i:>3}]  OK (via {matched_via})  A='{col_a}'  B='{col_b}'  ->  {os.path.basename(path)}", "ok")

    if merged_count == 0:
        raise ValueError("Nothing matched - no PDF was written.")

    os.makedirs(os.path.dirname(output_path) or ".", exist_ok=True)
    with open(output_path, "wb") as f:
        writer.write(f)

    return merged_count, missing_rows


# ---------------------------------------------------------------------------
# Tool 2: JO ID Search Compiler - core logic (same matching/ordering rules
# as the original script; now parameterized instead of hardcoded)
# ---------------------------------------------------------------------------

def run_id_search(ids_raw, target_file, partial_match, log_fn):
    """
    ids_raw: raw multi-line string pasted by the user (one ID per line)
    target_file: path to the Excel workbook to search -- any of
        .xlsx / .xlsm / .xls all work (format is auto-detected from the
        file's actual contents, not its extension)
    partial_match: True = cell "contains" the ID, False = exact cell match
    log_fn: function that accepts (message, tag) and displays it

    Returns a pandas DataFrame ready to export, or raises an Exception.
    """
    all_ids = [line.strip() for line in ids_raw.strip().split("\n") if line.strip()]
    if not all_ids:
        raise ValueError("Please paste at least one ID.")

    # Preserve first-seen order, but allow duplicates in the pasted list
    unique_ordered_ids = list(dict.fromkeys(all_ids))
    id_order = {str(v): idx for idx, v in enumerate(unique_ordered_ids)}
    search_set = set(id_order.keys())

    log_fn(f"Loaded {len(all_ids)} pasted ID line(s)  ->  {len(unique_ordered_ids)} unique ID(s) to search for.", "info")

    if not os.path.isfile(target_file):
        raise ValueError(f"Target file not found:\n{target_file}")

    log_fn(f"Opening workbook (this can take a moment for large files)...", "info")
    # Read every sheet as raw, header-less rows (dtype=object keeps blank
    # cells as NaN/None and numbers as numbers) so row numbers below line up
    # 1-for-1 with what you'd see in Excel -- and so this works no matter
    # whether the file is really .xlsx, .xlsm, or legacy .xls.
    sheets = _read_excel(target_file, sheet_name=None, header=None, dtype=object)
    sheet_names = list(sheets.keys())
    log_fn(f"Workbook has {len(sheet_names)} sheet(s): {', '.join(sheet_names)}", "info")

    matches = []          # list of (search_id, sheet_name, row_number)
    found_ids = set()
    match_counts = {}

    for sheet_name, df in sheets.items():
        for row_idx, row in enumerate(df.itertuples(index=False, name=None), start=1):
            for value in row:
                if value is None or (isinstance(value, float) and pd.isna(value)):
                    continue
                cell_str = str(value).strip()
                if not cell_str:
                    continue
                for search_id in search_set:
                    hit = (search_id in cell_str) if partial_match else (cell_str == search_id)
                    if hit:
                        matches.append((search_id, sheet_name, row_idx))
                        found_ids.add(search_id)
                        match_counts[search_id] = match_counts.get(search_id, 0) + 1

    # Per-ID log, in the user's original order
    for idx, uid in enumerate(unique_ordered_ids, start=1):
        if uid in found_ids:
            n = match_counts.get(uid, 0)
            plural = "match" if n == 1 else "matches"
            log_fn(f"[{idx:>3}]  FOUND    ID='{uid}'  ->  {n} {plural}", "ok")
        else:
            log_fn(f"[{idx:>3}]  MISSING  ID='{uid}'  ->  not found anywhere in the workbook", "missing")

    missing_ids = search_set - found_ids

    if not matches:
        raise ValueError("Nothing matched - no CSV was written.")

    # Pull full row data for every unique (sheet, row) that matched
    unique_rows = set((sheet, row) for (_, sheet, row) in matches)
    row_data_cache = {}
    max_cols = 0
    for sheet, row_num in unique_rows:
        vals = sheets[sheet].iloc[row_num - 1].tolist()
        row_data_cache[(sheet, row_num)] = vals
        max_cols = max(max_cols, len(vals))

    rows_data = []
    for search_id, sheet, row_num in matches:
        row_vals = row_data_cache[(sheet, row_num)]
        row_dict = OrderedDict()
        row_dict["Matched_ID"] = search_id
        row_dict["Source_Sheet"] = sheet
        row_dict["Original_Row"] = row_num
        for i, val in enumerate(row_vals):
            row_dict[f"Col{i + 1}"] = val
        rows_data.append(row_dict)

    # Sort by the user's original ID order
    rows_data.sort(key=lambda d: id_order.get(d["Matched_ID"], 99999))

    for rd in rows_data:
        for i in range(1, max_cols + 1):
            if f"Col{i}" not in rd:
                rd[f"Col{i}"] = None

    df = pd.DataFrame(rows_data)
    col_order = ["Matched_ID", "Source_Sheet", "Original_Row"] + [f"Col{i}" for i in range(1, max_cols + 1)]
    df = df[col_order]

    return df, missing_ids, len(matches)


