    def _set_app_icon(self, root):
        """Sets the window / taskbar icon from the embedded logo. Never
        crashes the app if this fails for any reason."""
        try:
            if self._logo_home_img is not None:
                root.iconphoto(True, self._logo_home_img)
        except tk.TclError:
            pass

    # -- container management / screen transitions -----------------------

    def _clear_container(self):
        for widget in self.container.winfo_children():
            widget.destroy()

    def _switch_screen(self, build_fn, loading_text="Loading..."):
        """Swap the visible screen for a new one. Shows a brief centered
        spinner + message first, then clears and builds the new screen.
        Deliberately NOT a pixel-based slide/place animation -- that
        approach sized itself off self.root.winfo_width()/height(), which
        breaks (looks "zoomed"/cropped) under Windows display scaling.
        Everything here stays on the normal pack() geometry manager, which
        sizes correctly regardless of DPI settings."""
        self._loading_gen = getattr(self, "_loading_gen", 0) + 1
        gen = self._loading_gen

        self._clear_container()
        self._show_loading(loading_text, gen)
        self.root.after(260, lambda: self._finish_switch(build_fn, gen))

    def _show_loading(self, text, gen):
        center = tk.Frame(self.container, bg=Theme.bg)
        center.place(relx=0.5, rely=0.5, anchor="center")
        spin_label = tk.Label(
            center, text="\u25D0", font=(FONT_FAMILY, 30), bg=Theme.bg, fg=Theme.accent,
        )
        spin_label.pack()
        tk.Label(
            center, text=text, font=(FONT_FAMILY, 11), bg=Theme.bg, fg=Theme.text_muted,
        ).pack(pady=(10, 0))
        self._spin_loading(spin_label, 0, gen)

    def _spin_loading(self, label, i, gen):
        if gen != self._loading_gen:
            return  # a newer switch started; let this one die quietly
        frames = ["\u25D0", "\u25D3", "\u25D1", "\u25D2"]
        try:
            label.configure(text=frames[i % len(frames)])
        except tk.TclError:
            return  # widget was destroyed already
        self.root.after(100, lambda: self._spin_loading(label, i + 1, gen))

    def _finish_switch(self, build_fn, gen):
        if gen != self._loading_gen:
            return
        self._clear_container()
        build_fn(self.container)

    def show_home(self):
        self._switch_screen(self._build_home_screen, "Loading Home...")

