    def _build_home_option_card(self, parent, icon, title, desc, command, width=250, height=230):
        outer = tk.Frame(parent, bg=Theme.border, cursor="hand2")
        inner = tk.Frame(outer, bg=Theme.card, width=width, height=height)
        inner.pack(padx=1, pady=1)
        inner.pack_propagate(False)

        content = tk.Frame(inner, bg=Theme.card)
        content.place(relx=0.5, rely=0.5, anchor="center")

        tk.Label(content, text=icon, font=(FONT_FAMILY, 34), bg=Theme.card, fg=Theme.accent).pack(pady=(0, 10))
        tk.Label(content, text=title, font=(FONT_FAMILY, 13, "bold"), bg=Theme.card, fg=Theme.text).pack()
        tk.Label(
            content, text=desc, font=(FONT_FAMILY, 9), bg=Theme.card, fg=Theme.text_muted,
            justify="center",
        ).pack(pady=(8, 14))

        HoverButton(
            content, bg=Theme.accent, hover_bg=Theme.accent_hover,
            text="Open  \u2192", font=(FONT_FAMILY, 9, "bold"),
            padx=14, pady=6, command=command,
        ).pack()

        # Make the whole card clickable, not just the button
        def bind_click(widget):
            widget.bind("<Button-1>", lambda e: command())
            for child in widget.winfo_children():
                bind_click(child)

        bind_click(inner)
        # (the button itself already triggers `command` via its own click)

        def on_enter(e):
            outer.configure(bg=Theme.accent)

        def on_leave(e):
            outer.configure(bg=Theme.border)

        outer.bind("<Enter>", on_enter)
        outer.bind("<Leave>", on_leave)

        return outer

