    def _merge_browse_source(self):
        folder = filedialog.askdirectory(title="Select folder containing source PDFs")
        if folder:
            self.merge_source_var.set(folder)

    def _merge_browse_output(self):
        path = filedialog.asksaveasfilename(
            title="Choose where to save the merged PDF",
            defaultextension=".pdf",
            filetypes=[("PDF files", "*.pdf")],
            initialfile="merged.pdf",
        )
        if path:
            self.merge_output_var.set(path)

    def _merge_on_run(self):
        col_a_lines = [line.strip() for line in self.merge_col_a_text.get("1.0", "end").splitlines()]
        col_b_lines = [line.strip() for line in self.merge_col_b_text.get("1.0", "end").splitlines()]

        while col_a_lines and col_a_lines[-1] == "":
            col_a_lines.pop()
        while col_b_lines and col_b_lines[-1] == "":
            col_b_lines.pop()

        if not col_a_lines:
            messagebox.showerror("Missing data", "Please paste at least Column A values.")
            return

        max_len = max(len(col_a_lines), len(col_b_lines))
        col_a_lines += [""] * (max_len - len(col_a_lines))
        col_b_lines += [""] * (max_len - len(col_b_lines))

        order_list = list(zip(col_a_lines, col_b_lines))

        source_folder = self.merge_source_var.get().strip()
        output_path = self.merge_output_var.get().strip()

        if not source_folder or not output_path:
            messagebox.showerror("Missing info", "Please choose both a source folder and an output file.")
            return

        self.merge_log.clear()
        self.merge_run_button.configure(state="disabled")
        self.merge_spinner.start(PDF_MERGE_MESSAGES)
        self.merge_progress.start(12)

        thread = threading.Thread(
            target=self._merge_worker, args=(order_list, source_folder, output_path), daemon=True
        )
        thread.start()

    def _merge_worker(self, order_list, source_folder, output_path):
        try:
            merged_count, missing_rows = run_merge(order_list, source_folder, output_path, self.merge_log.log)
            self.merge_log.log("=" * 66, "info")
            self.merge_log.log(f"DONE. Merged {merged_count} unique PDF(s) into:\n{output_path}", "ok")
            if missing_rows:
                self.merge_log.log(f"\n{len(missing_rows)} row(s) had NO matching PDF:", "missing")
                for i, a, b in missing_rows:
                    b_display = f"00{b}" if b else "(none)"
                    self.merge_log.log(f"   Row {i}: A='{a}'  |  B lookup='{b_display}'", "missing")
                self.root.after(0, lambda: self.merge_spinner.stop("Done (with missing files)", Theme.warning))
                self.root.after(0, lambda: messagebox.showwarning(
                    "Done with some missing files",
                    f"Merged {merged_count} PDF(s), but {len(missing_rows)} row(s) had no matching file. "
                    f"See the log for details."
                ))
            else:
                self.root.after(0, lambda: self.merge_spinner.stop("Done", Theme.success))
                self.root.after(0, lambda: messagebox.showinfo(
                    "Success", f"Merged {merged_count} PDF(s) into:\n{output_path}"
                ))
        except Exception as e:
            self.merge_log.log(f"ERROR: {e}", "error")
            self.root.after(0, lambda: self.merge_spinner.stop("Error", Theme.error))
            self.root.after(0, lambda: messagebox.showerror("Error", str(e)))
        finally:
            self.root.after(0, self.merge_progress.stop)
            self.root.after(0, lambda: self.merge_run_button.configure(state="normal"))

